use std::sync::atomic::{AtomicBool, Ordering};

pub struct SpinLock { locked: AtomicBool }

impl SpinLock {
    pub const fn new() -> Self { Self { locked: AtomicBool::new(false) } }
    pub fn lock(&self) {
        while self.locked.⟦op⟧(false, true, Ordering::Acquire, Ordering::Relaxed).⟦res⟧ {
            std::hint::spin_loop();
        }
    }
    pub fn unlock(&self) { self.locked.store(false, Ordering::Release); }
}

fn main() {}

tests:
#[test]
fn test_spinlock() {
    use std::sync::Arc;
    let lock = Arc::new(SpinLock::new());
    lock.lock();
    let l2 = lock.clone();
    let h = std::thread::spawn(move || { l2.lock(); l2.unlock(); });
    std::thread::sleep(std::time::Duration::from_millis(50));
    assert!(!h.is_finished());
    lock.unlock();
    h.join().unwrap();
}
